/**
 * @name User input flowing to pyparsing parse operations
 * @description User-controlled data flowing to parsing operations that could lead to injection
 * @kind path-problem
 * @problem.severity warning
 * @id py/parsing-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ParsingInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Look for parse methods in pyparsing that take user input
      call = API::moduleImport("pyparsing").getMember(["parseString", "parseFile", "scanString", "transformString"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ParsingInjectionFlow = TaintTracking::Global<ParsingInjectionConfig>;
import ParsingInjectionFlow::PathGraph

from ParsingInjectionFlow::PathNode source, ParsingInjectionFlow::PathNode sink
where ParsingInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input flows to pyparsing parse operation $@.", source.getNode(), "user input"

/**
 * @name Parse Action Injection in pyparsing
 * @description Untrusted input flowing to parse action execution could lead to code injection
 * @kind path-problem
 * @problem.severity error
 * @id py/parse-action-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ParseActionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to setParseAction or addParseAction
    exists(API::CallNode call |
      call = API::moduleImport("pyparsing").getMember(["setParseAction", "addParseAction", "set_parse_action", "add_parse_action"]).getACall() and
      // The parse action function/callable argument
      sink = call.getArg(0)
    )
  }
}

module ParseActionFlow = TaintTracking::Global<ParseActionConfig>;
import ParseActionFlow::PathGraph

from ParseActionFlow::PathNode source, ParseActionFlow::PathNode sink
where ParseActionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Parse action injection: user input flows to parse action $@.", source.getNode(), "user input"
